program.compute:
options = read('/input/options')
result = []
for k in range(goal['min_count'], goal['max_count'] + 1):
    for group in combinations(options, k):
        ids = [row['id'] for row in group]
        if valid(ids):
            result = ids
            break
    if len(result) > 0:
        break

program.effects:
artifact = read('/output/selection')
if artifact == None:
    write('/output/selection', result)
    artifact = result
if status('report') == 'not_sent':
    send('report', 'team', artifact)
if exists('/tmp/cache'):
    delete('/tmp/cache')

